    {!leftCollapsed&&<SidebarResizer side="left" onCommit={width=>bookmarks.savePanelWidth('left',width)} note={note}/>} {!rightCollapsed&&<SidebarResizer side="right" onCommit={width=>bookmarks.savePanelWidth('right',width)} note={note}/>}
