      {['resident','place','node','agent','text_file','pulse'].includes(modal)&&<><label>编号<input aria-label="模板编号" value={wizard.id??''} onChange={e=>patchWizard('id',e.target.value)}/></label><label>名称<input aria-label="模板名称" value={wizard.name??''} onChange={e=>patchWizard('name',e.target.value)}/></label></>}
