      {modal==='resident'&&<><div className="two-columns"><label>职业<select value={wizard.role} onChange={e=>patchWizard('role',e.target.value)}>{['resident','miner','woodcutter','smith','wanderer','child'].map(v=><option key={v}>{v}</option>)}</select></label><label>性别<select value={wizard.gender} onChange={e=>patchWizard('gender',e.target.value)}><option value="unspecified">未指定</option><option value="male">男性</option><option value="female">女性</option></select></label></div><label>初始场所<select aria-label="居民初始场所" value={wizard.place} onChange={e=>patchWizard('place',e.target.value)}><option value="">选择场所</option>{doc.network.nodes.filter(n=>n.modules['world.address']).map(n=><option key={n.node_id} value={n.node_id}>{n.name}</option>)}</select></label><label>初始金币<input type="number" min="0" value={wizard.coins} onChange={e=>patchWizard('coins',Number(e.target.value))}/></label><label>人格（系统提示词）<textarea aria-label="居民人格" rows={3} value={wizard.personality} onChange={e=>patchWizard('personality',e.target.value)}/></label><label>初始动机（仅首次输入）<textarea aria-label="居民动机" rows={2} value={wizard.motivation} onChange={e=>patchWizard('motivation',e.target.value)}/></label></>}
      {modal==='connect'&&<><label>连接起点<select aria-label="连接起点" value={wizard.source??''} onChange={e=>patchWizard('source',e.target.value)}><option value="">选择起点节点</option>{doc.network.nodes.map(n=><option key={n.node_id} value={n.node_id}>{n.name} · {n.node_id}</option>)}</select></label><label>连接终点<select aria-label="连接终点" value={wizard.target??''} onChange={e=>patchWizard('target',e.target.value)}><option value="">选择目标节点</option>{doc.network.nodes.map(n=><option key={n.node_id} value={n.node_id}>{n.name} · {n.node_id}</option>)}</select></label><label className="checkbox"><input type="checkbox" checked={wizard.reciprocal} onChange={e=>patchWizard('reciprocal',e.target.checked)}/>反向也建立连接（适合道路）</label><div className="two-columns"><label>门槛<input type="number" min="0" value={wizard.threshold} onChange={e=>patchWizard('threshold',Number(e.target.value))}/></label><label>倍率<input type="number" min="0" value={wizard.multiplier} onChange={e=>patchWizard('multiplier',Number(e.target.value))}/></label></div>{wizard.sourceModule&&<p>专有连接 · {wizard.sourceModule}</p>}<ChannelList label="连接频道" value={Array.isArray(wizard.channels)?wizard.channels:wizard.channels.split(',').map(s=>s.trim()).filter(Boolean)} mode={wizard.channel_mode??'allow'} onChange={channels=>patchWizard('channels',channels)} onMode={mode=>patchWizard('channel_mode',mode)}/></>}
